import itertools

def check_x_final(M, x):
    limit = M
    W = []
    for w in itertools.product(range(-limit, x[0]+1), repeat=M):
        if all(w[i] <= x[i] for i in range(M)):
            W.append(list(w))

    w_to_idx = {tuple(w): i for i, w in enumerate(W)}
    is_bob_winning = [False] * len(W)

    changed = True
    while changed:
        changed = False
        for i, w in enumerate(W):
            if is_bob_winning[i]: continue
            for k in range(1, M):
                U1 = [j for j in range(k) if w[j] == x[j]]
                U2 = [j for j in range(k, M) if w[j] == x[j]]
                if U1 and U2:
                    is_bob_winning[i] = True
                    changed = True; break
                if U1:
                    w_next = list(w)
                    for j in range(k): w_next[j] -= 1
                    for j in range(k, M): w_next[j] += 1
                    w_next_tuple = tuple(w_next)
                    if w_next_tuple not in w_to_idx or is_bob_winning[w_to_idx[w_next_tuple]]:
                        is_bob_winning[i] = True
                        changed = True; break
                if U2:
                    w_next = list(w)
                    for j in range(k): w_next[j] += 1
                    for j in range(k, M): w_next[j] -= 1
                    w_next_tuple = tuple(w_next)
                    if w_next_tuple not in w_to_idx or is_bob_winning[w_to_idx[w_next_tuple]]:
                        is_bob_winning[i] = True
                        changed = True; break
                if not U1 and not U2:
                    w_next1 = list(w)
                    for j in range(k): w_next1[j] -= 1
                    for j in range(k, M): w_next1[j] += 1
                    w_next1_tuple = tuple(w_next1)
                    w_next2 = list(w)
                    for j in range(k): w_next2[j] += 1
                    for j in range(k, M): w_next2[j] -= 1
                    w_next2_tuple = tuple(w_next2)
                    if (w_next1_tuple not in w_to_idx or is_bob_winning[w_to_idx[w_next1_tuple]]) and \
                       (w_next2_tuple not in w_to_idx or is_bob_winning[w_to_idx[w_next2_tuple]]):
                        is_bob_winning[i] = True
                        changed = True; break

    initial_w = tuple([0]*M)
    if initial_w not in w_to_idx: return False
    return not is_bob_winning[w_to_idx[initial_w]]

def find_min_n_correct(M):
    for N in range(0, 100):
        def get_x_tuples(n, m):
            if m == 1:
                yield (n,)
                return
            for i in range(n + 1):
                for rest in get_x_tuples(n - i, m - 1):
                    yield (i,) + rest

        for x in get_x_tuples(N, M):
            if check_x_final(M, x):
                return N
    return None

