import itertools

def solve_m_correct(m):
    # A state is safe if for all k, there exists a move to a state that is safe.
    # Since the sum can increase, we need to bound the values of x_i.
    # If x_i >= m for all i, then any move will result in x_i' >= m-1 >= 1, so it's safe.

    limit = m + 1
    states = []
    for x in itertools.product(range(1, limit + 1), repeat=m):
        states.append(x)

    safe = set()
    for x in states:
        if all(xi >= m for xi in x):
            safe.add(x)

    while True:
        new_safe = set()
        for x in states:
            if x in safe:
                new_safe.add(x)
                continue

            is_x_safe = True
            for k in range(1, m):
                move1 = list(x)
                for i in range(k): move1[i] += 1
                for i in range(k, m): move1[i] -= 1

                move2 = list(x)
                for i in range(k): move2[i] -= 1
                for i in range(k, m): move2[i] += 1

                m1_safe = all(v >= 1 for v in move1) and (all(v >= m for v in move1) or tuple(move1) in safe)
                m2_safe = all(v >= 1 for v in move2) and (all(v >= m for v in move2) or tuple(move2) in safe)

                if not (m1_safe or m2_safe):
                    is_x_safe = False
                    break
            if is_x_safe:
                new_safe.add(x)

        if new_safe == safe:
            break
        safe = new_safe

    min_n = float('inf')
    for x in safe:
        min_n = min(min_n, sum(x))
    return min_n

for m in range(2, 7):
    print(f"m={m}, n={solve_m_correct(m)}")
